create extension if not exists pgcrypto;

create type public.app_role as enum ('USER','MODERATOR','ADMIN','SUPER_ADMIN');
create type public.account_status as enum ('ACTIVE','SUSPENDED','BANNED');
create type public.region_code as enum ('EU WEST','EU NORTH/EAST','EU OTHER');
create type public.player_role as enum ('DUELIST','CONTROLLER','INITIATOR','SENTINEL','FLEX');
create type public.leadership_role as enum ('CAPTAIN','CO_CAPTAIN','MEMBER');
create type public.roster_slot as enum ('STARTER','SUBSTITUTE');
create type public.invite_state as enum ('PENDING','ACCEPTED','DECLINED','CANCELLED','EXPIRED');
create type public.application_state as enum ('PENDING','ACCEPTED','DECLINED','CANCELLED');
create type public.season_state as enum ('UPCOMING','ACTIVE','COMPLETED');
create type public.tournament_state as enum ('DRAFT','PUBLISHED','REGISTRATION_OPEN','REGISTRATION_CLOSED','CHECK_IN','LIVE','COMPLETED','ARCHIVED');
create type public.registration_state as enum ('PENDING','REGISTERED','WAITLISTED','CHECKED_IN','WITHDRAWN','REJECTED','NO_SHOW','DISQUALIFIED');
create type public.match_state as enum ('UPCOMING','READY','LIVE','AWAITING_CONFIRMATION','COMPLETED','DISPUTED','FORFEIT');
create type public.dispute_state as enum ('OPEN','UNDER_REVIEW','RESOLVED','REJECTED');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text not null unique check(username ~ '^[A-Za-z0-9_]{3,20}$'), riot_game_name text not null, riot_tag text not null, riot_verified boolean not null default false, region public.region_code not null, primary_role public.player_role not null, secondary_role public.player_role, avatar_url text, bio text not null default '', looking_for_team boolean not null default false, availability text not null default '', account_status public.account_status not null default 'ACTIVE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'USER');
create table public.teams (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, tag varchar(6) not null, region public.region_code not null, description text not null default '', logo_url text, recruiting boolean not null default false, suspended_at timestamptz, disbanded_at timestamptz, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.team_members (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, user_id uuid not null references public.profiles(id), leadership public.leadership_role not null default 'MEMBER', roster_slot public.roster_slot not null, active boolean not null default true, joined_at timestamptz not null default now(), unique(team_id,user_id));
create table public.team_invites (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, invited_user_id uuid not null references public.profiles(id), invited_by uuid not null references public.profiles(id), state public.invite_state not null default 'PENDING', expires_at timestamptz not null default now()+interval '7 days', created_at timestamptz not null default now());
create table public.team_applications (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, user_id uuid not null references public.profiles(id), preferred_role public.player_role not null, message varchar(500), state public.application_state not null default 'PENDING', created_at timestamptz not null default now());
create table public.seasons (id uuid primary key default gen_random_uuid(), name text not null, code text not null unique, start_at timestamptz not null, end_at timestamptz not null, status public.season_state not null);
create table public.tournaments (id uuid primary key default gen_random_uuid(), slug text not null unique, code text not null, name text not null, edition text not null, description text not null, category text not null, tier text not null check(tier in ('COMMUNITY','OPEN','PREMIER','PEAK LEAGUE','CHAMPIONSHIP')), status public.tournament_state not null default 'DRAFT', region text not null default 'EUROPE', format text not null default '5V5', team_size int not null default 5 check(team_size=5), max_teams int not null check(max_teams in (8,16,32,64)), max_substitutes int not null default 2 check(max_substitutes between 0 and 2), structure text not null default 'SINGLE ELIMINATION' check(structure='SINGLE ELIMINATION'), best_of int not null check(best_of in (1,3)), final_best_of int not null check(final_best_of in (1,3,5)), registration_open_at timestamptz not null, registration_close_at timestamptz not null, roster_lock_at timestamptz not null, check_in_open_at timestamptz not null, check_in_close_at timestamptz not null, start_at timestamptz not null, end_at timestamptz, rules text not null, prize_description text, banner_url text, cover_url text, season_id uuid references public.seasons(id), visibility text not null default 'PUBLIC' check(visibility in ('PUBLIC','UNLISTED')), waitlist_enabled boolean not null default true, require_complete_roster boolean not null default true, created_at timestamptz not null default now(), published_at timestamptz, check(registration_open_at<registration_close_at and registration_close_at<=roster_lock_at and roster_lock_at<=check_in_open_at and check_in_open_at<check_in_close_at and check_in_close_at<=start_at));
create table public.tournament_registrations (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), team_id uuid not null references public.teams(id), registered_by uuid not null references public.profiles(id), status public.registration_state not null, waitlist_position int, checked_in_at timestamptz, created_at timestamptz not null default now(), unique(tournament_id,team_id));
create table public.tournament_roster_members (id uuid primary key default gen_random_uuid(), registration_id uuid not null references public.tournament_registrations(id) on delete cascade, player_id uuid not null references public.profiles(id), roster_slot public.roster_slot not null, role_at_registration public.player_role not null, created_at timestamptz not null default now(), unique(registration_id,player_id));
create table public.matches (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), round text not null, bracket_position int not null, team_a_id uuid references public.teams(id), team_b_id uuid references public.teams(id), scheduled_at timestamptz, best_of int not null check(best_of in (1,3,5)), status public.match_state not null default 'UPCOMING', team_a_score int, team_b_score int, winner_team_id uuid references public.teams(id), next_match_id uuid references public.matches(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table public.match_ready_states (match_id uuid not null references public.matches(id) on delete cascade, team_id uuid not null references public.teams(id), marked_by uuid not null references public.profiles(id), ready_at timestamptz not null default now(), primary key(match_id,team_id));
create table public.match_player_participation (match_id uuid not null references public.matches(id) on delete cascade, player_id uuid not null references public.profiles(id), team_id uuid not null references public.teams(id), participated boolean not null default true, created_at timestamptz not null default now(), primary key(match_id,player_id));
create table public.match_result_submissions (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id), submitted_by uuid not null references public.profiles(id), team_a_score int not null check(team_a_score>=0), team_b_score int not null check(team_b_score>=0), evidence_path text, confirmed_by uuid references public.profiles(id), confirmed_at timestamptz, created_at timestamptz not null default now());
create table public.match_room_messages (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id) on delete cascade, user_id uuid not null references public.profiles(id), team_id uuid references public.teams(id), message varchar(1000) not null, removed_at timestamptz, created_at timestamptz not null default now());
create table public.disputes (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches(id), opened_by uuid not null references public.profiles(id), reason text not null, state public.dispute_state not null default 'OPEN', admin_notes text, resolution text, resolved_by uuid references public.profiles(id), created_at timestamptz not null default now(), resolved_at timestamptz);
create table public.dispute_evidence (id uuid primary key default gen_random_uuid(), dispute_id uuid not null references public.disputes(id) on delete cascade, uploaded_by uuid not null references public.profiles(id), storage_path text not null, created_at timestamptz not null default now());
create table public.tournament_point_events (id uuid primary key default gen_random_uuid(), season_id uuid not null references public.seasons(id), tournament_id uuid not null references public.tournaments(id), match_id uuid references public.matches(id), team_id uuid not null references public.teams(id), player_id uuid references public.profiles(id), type text not null, base_points int not null, multiplier numeric(4,2) not null, final_points numeric(10,2) generated always as (base_points*multiplier) stored, created_at timestamptz not null default now(), created_by_system boolean not null default true, reversed_at timestamptz, reversal_reason text);
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, body text not null, href text, read_at timestamptz, created_at timestamptz not null default now());
create table public.admin_announcements (id uuid primary key default gen_random_uuid(), title text not null, message text not null, target text not null, tournament_id uuid references public.tournaments(id), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(), actor uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());

create unique index one_active_team_per_user on public.team_members(user_id) where active;
create index profiles_username_idx on public.profiles(username);
create index teams_slug_idx on public.teams(slug);
create index team_members_user_idx on public.team_members(user_id,active);
create index tournaments_slug_idx on public.tournaments(slug);
create index tournaments_status_idx on public.tournaments(status,start_at);
create index registrations_tournament_team_idx on public.tournament_registrations(tournament_id,team_id,status);
create index matches_tournament_status_idx on public.matches(tournament_id,status);
create index notifications_user_read_idx on public.notifications(user_id,read_at,created_at desc);
create index tp_season_team_player_idx on public.tournament_point_events(season_id,team_id,player_id) where reversed_at is null;
create index disputes_status_idx on public.disputes(state,created_at);

create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from user_roles where user_id=auth.uid() and role in ('MODERATOR','ADMIN','SUPER_ADMIN')) $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from user_roles where user_id=auth.uid() and role in ('ADMIN','SUPER_ADMIN')) $$;
create or replace function public.is_team_leader(p_team uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from team_members where team_id=p_team and user_id=auth.uid() and active and leadership in ('CAPTAIN','CO_CAPTAIN')) $$;
create or replace function public.can_access_match(p_match uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_staff() or exists(select 1 from matches m join tournament_registrations r on r.tournament_id=m.tournament_id and r.team_id in(m.team_a_id,m.team_b_id) join tournament_roster_members tr on tr.registration_id=r.id where m.id=p_match and tr.player_id=auth.uid()) $$;

create or replace function public.create_team(p_name text,p_tag text,p_region region_code,p_description text,p_recruiting boolean) returns uuid language plpgsql security definer set search_path=public as $$ declare team uuid; team_slug text; begin if exists(select 1 from team_members where user_id=auth.uid() and active) then raise exception 'ALREADY_ON_TEAM'; end if; if p_tag!~'^[A-Za-z0-9]{2,6}$' then raise exception 'INVALID_TAG'; end if; team_slug:=trim(both '-' from regexp_replace(lower(p_name),'[^a-z0-9]+','-','g')); insert into teams(slug,name,tag,region,description,recruiting,created_by) values(team_slug,p_name,upper(p_tag),p_region,coalesce(p_description,''),p_recruiting,auth.uid()) returning id into team; insert into team_members(team_id,user_id,leadership,roster_slot) values(team,auth.uid(),'CAPTAIN','STARTER'); return team; end $$;
create or replace function public.apply_to_team(p_team uuid,p_role player_role,p_message text) returns uuid language plpgsql security definer set search_path=public as $$ declare result uuid; begin if exists(select 1 from team_members where user_id=auth.uid() and active) then raise exception 'ALREADY_ON_TEAM'; end if; if not exists(select 1 from teams where id=p_team and recruiting and disbanded_at is null and suspended_at is null) then raise exception 'NOT_RECRUITING'; end if; if exists(select 1 from team_applications where team_id=p_team and user_id=auth.uid() and state='PENDING') then raise exception 'DUPLICATE_APPLICATION'; end if; insert into team_applications(team_id,user_id,preferred_role,message) values(p_team,auth.uid(),p_role,left(p_message,500)) returning id into result; return result; end $$;
create or replace function public.set_match_ready(p_match uuid,p_team uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_team_leader(p_team) or not public.can_access_match(p_match) then raise exception 'NOT_AUTHORIZED'; end if; insert into match_ready_states(match_id,team_id,marked_by) values(p_match,p_team,auth.uid()) on conflict(match_id,team_id) do update set marked_by=excluded.marked_by,ready_at=now(); if (select count(*) from match_ready_states where match_id=p_match)=2 then update matches set status='READY' where id=p_match and status='UPCOMING'; end if; end $$;
create or replace function public.submit_match_result(p_match uuid,p_team_a_score int,p_team_b_score int,p_players uuid[],p_evidence text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare result uuid; begin if not public.can_access_match(p_match) then raise exception 'NOT_AUTHORIZED'; end if; if p_team_a_score=p_team_b_score or array_length(p_players,1)<>5 then raise exception 'INVALID_RESULT'; end if; if exists(select 1 from match_result_submissions where match_id=p_match and confirmed_at is null) then raise exception 'RESULT_ALREADY_SUBMITTED'; end if; insert into match_result_submissions(match_id,submitted_by,team_a_score,team_b_score,evidence_path) values(p_match,auth.uid(),p_team_a_score,p_team_b_score,p_evidence) returning id into result; update matches set status='AWAITING_CONFIRMATION' where id=p_match and status in('READY','LIVE'); return result; end $$;

create or replace function public.register_tournament_team(p_tournament uuid,p_team uuid,p_roster jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare r uuid; t tournaments%rowtype; count_registered int; begin if not is_team_leader(p_team) then raise exception 'TEAM_LEADER_REQUIRED'; end if; select * into t from tournaments where id=p_tournament for update; if t.status<>'REGISTRATION_OPEN' or now() not between t.registration_open_at and t.registration_close_at then raise exception 'REGISTRATION_CLOSED'; end if; if jsonb_array_length(p_roster)<5 or jsonb_array_length(p_roster)>5+t.max_substitutes then raise exception 'INVALID_ROSTER_SIZE'; end if; select count(*) into count_registered from tournament_registrations where tournament_id=p_tournament and status in ('REGISTERED','CHECKED_IN'); insert into tournament_registrations(tournament_id,team_id,registered_by,status,waitlist_position) values(p_tournament,p_team,auth.uid(),case when count_registered<t.max_teams then 'REGISTERED'::registration_state else 'WAITLISTED'::registration_state end,case when count_registered>=t.max_teams then (select count(*)+1 from tournament_registrations where tournament_id=p_tournament and status='WAITLISTED') end) returning id into r; insert into tournament_roster_members(registration_id,player_id,roster_slot,role_at_registration) select r,(x->>'player_id')::uuid,(x->>'roster_slot')::roster_slot,(x->>'role')::player_role from jsonb_array_elements(p_roster)x join team_members m on m.team_id=p_team and m.user_id=(x->>'player_id')::uuid and m.active; if (select count(*) from tournament_roster_members where registration_id=r)<>jsonb_array_length(p_roster) then raise exception 'INVALID_ROSTER_MEMBER'; end if; return r; end $$;
create or replace function public.check_in_tournament_team(p_registration uuid) returns void language plpgsql security definer set search_path=public as $$ declare x tournament_registrations%rowtype; t tournaments%rowtype; begin select * into x from tournament_registrations where id=p_registration for update; if not is_team_leader(x.team_id) then raise exception 'TEAM_LEADER_REQUIRED'; end if; select * into t from tournaments where id=x.tournament_id; if now() not between t.check_in_open_at and t.check_in_close_at then raise exception 'CHECK_IN_CLOSED'; end if; update tournament_registrations set status='CHECKED_IN',checked_in_at=now() where id=p_registration and status='REGISTERED'; end $$;
create or replace function public.confirm_match_result(p_submission uuid) returns void language plpgsql security definer set search_path=public as $$ declare s match_result_submissions%rowtype; m matches%rowtype; winner uuid; begin select * into s from match_result_submissions where id=p_submission for update; select * into m from matches where id=s.match_id for update; if m.status<>'AWAITING_CONFIRMATION' then raise exception 'INVALID_MATCH_STATE'; end if; winner:=case when s.team_a_score>s.team_b_score then m.team_a_id else m.team_b_id end; update match_result_submissions set confirmed_by=auth.uid(),confirmed_at=now() where id=p_submission; update matches set status='COMPLETED',team_a_score=s.team_a_score,team_b_score=s.team_b_score,winner_team_id=winner,completed_at=now() where id=m.id; end $$;
create or replace function public.open_match_dispute(p_submission uuid,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$ declare d uuid; mid uuid; begin select match_id into mid from match_result_submissions where id=p_submission; insert into disputes(match_id,opened_by,reason) values(mid,auth.uid(),p_reason) returning id into d; update matches set status='DISPUTED' where id=mid and status='AWAITING_CONFIRMATION'; return d; end $$;
create or replace function public.transition_tournament(p_tournament uuid,p_next tournament_state) returns void language plpgsql security definer set search_path=public as $$ declare current tournament_state; begin if not is_admin() then raise exception 'ADMIN_REQUIRED'; end if; select status into current from tournaments where id=p_tournament for update; if not ((current='DRAFT' and p_next='PUBLISHED') or (current='PUBLISHED' and p_next='REGISTRATION_OPEN') or (current='REGISTRATION_OPEN' and p_next='REGISTRATION_CLOSED') or (current='REGISTRATION_CLOSED' and p_next='CHECK_IN') or (current='CHECK_IN' and p_next='LIVE') or (current='LIVE' and p_next='COMPLETED') or (current='COMPLETED' and p_next='ARCHIVED')) then raise exception 'INVALID_TRANSITION'; end if; update tournaments set status=p_next,published_at=case when p_next='PUBLISHED' then coalesce(published_at,now()) else published_at end where id=p_tournament; insert into public.admin_audit_logs(actor,action,entity_type,entity_id,metadata) values(auth.uid(),'TOURNAMENT_STATE_CHANGED','TOURNAMENT',p_tournament,jsonb_build_object('from',current,'to',p_next)); end $$;
create or replace function public.promote_waitlisted_team(p_registration uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not is_admin() then raise exception 'ADMIN_REQUIRED'; end if; update tournament_registrations set status='REGISTERED',waitlist_position=null where id=p_registration and status='WAITLISTED'; insert into public.admin_audit_logs(actor,action,entity_type,entity_id) values(auth.uid(),'WAITLIST_PROMOTED','REGISTRATION',p_registration); end $$;

alter table public.profiles enable row level security;
alter table public.user_roles enable row level security;
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.team_invites enable row level security;
alter table public.team_applications enable row level security;
alter table public.seasons enable row level security;
alter table public.tournaments enable row level security;
alter table public.tournament_registrations enable row level security;
alter table public.tournament_roster_members enable row level security;
alter table public.matches enable row level security;
alter table public.match_ready_states enable row level security;
alter table public.match_player_participation enable row level security;
alter table public.match_result_submissions enable row level security;
alter table public.match_room_messages enable row level security;
alter table public.disputes enable row level security;
alter table public.dispute_evidence enable row level security;
alter table public.tournament_point_events enable row level security;
alter table public.notifications enable row level security;
alter table public.admin_announcements enable row level security;
alter table public.admin_audit_logs enable row level security;
create policy "public profiles read" on public.profiles for select using(account_status='ACTIVE');
create policy "own profile update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "own profile insert" on public.profiles for insert with check(id=auth.uid());
create policy "roles visible to owner and staff" on public.user_roles for select using(user_id=auth.uid() or public.is_staff());
create policy "public teams read" on public.teams for select using(disbanded_at is null);
create policy "public team memberships read" on public.team_members for select using(true);
create policy "own team invites read" on public.team_invites for select using(invited_user_id=auth.uid() or public.is_team_leader(team_id));
create policy "own applications read" on public.team_applications for select using(user_id=auth.uid() or public.is_team_leader(team_id));
create policy "published tournaments read" on public.tournaments for select using(status<>'DRAFT' or public.is_admin());
create policy "public seasons read" on public.seasons for select using(true);
create policy "public matches read" on public.matches for select using(exists(select 1 from tournaments t where t.id=tournament_id and t.status<>'DRAFT'));
create policy "public registrations read" on public.tournament_registrations for select using(exists(select 1 from tournaments t where t.id=tournament_id and t.status<>'DRAFT'));
create policy "public roster read" on public.tournament_roster_members for select using(exists(select 1 from tournament_registrations r join tournaments t on t.id=r.tournament_id where r.id=registration_id and t.status<>'DRAFT'));
create policy "match participants read ready" on public.match_ready_states for select using(public.can_access_match(match_id));
create policy "match participants read participation" on public.match_player_participation for select using(public.can_access_match(match_id));
create policy "match participants read results" on public.match_result_submissions for select using(public.can_access_match(match_id));
create policy "match participants chat read" on public.match_room_messages for select using(public.can_access_match(match_id));
create policy "match participants chat insert" on public.match_room_messages for insert with check(user_id=auth.uid() and public.can_access_match(match_id));
create policy "dispute participants read" on public.disputes for select using(public.can_access_match(match_id));
create policy "dispute evidence participants read" on public.dispute_evidence for select using(exists(select 1 from disputes d where d.id=dispute_id and public.can_access_match(d.match_id)));
create policy "public point ledger read" on public.tournament_point_events for select using(reversed_at is null);
create policy "own notifications read" on public.notifications for select using(user_id=auth.uid());
create policy "own notifications update" on public.notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "staff audit read" on public.admin_audit_logs for select using(public.is_staff());

insert into storage.buckets(id,name,public) values ('avatars','avatars',true),('team-logos','team-logos',true),('tournament-banners','tournament-banners',true),('dispute-evidence','dispute-evidence',false) on conflict(id) do nothing;
create policy "avatar owner insert" on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "team leaders upload logos" on storage.objects for insert to authenticated with check(bucket_id='team-logos' and public.is_team_leader(((storage.foldername(name))[1])::uuid));
create policy "admins upload tournaments" on storage.objects for insert to authenticated with check(bucket_id='tournament-banners' and public.is_admin());
create policy "eligible dispute evidence" on storage.objects for insert to authenticated with check(bucket_id='dispute-evidence');

